"""Independently replay each declared architecture example on frozen source."""

from hashlib import sha256
import json
from pathlib import Path
import re
import sys
from tempfile import TemporaryDirectory

from assess import execute, PATHS


ROOT = Path(__file__).resolve().parent
SECTION = re.compile(r"^##[ \t]+可执行示例[ \t]*\r?$", re.M)
NEXT_SECTION = re.compile(r"^#{1,2}[ \t]+\S", re.M)
FENCE = re.compile(r"\s*(`{3,}|~{3,})[ \t]*json[ \t]*\r?\n(.*?)\r?\n[ \t]{0,3}\1\s*", re.S)


def audit(source, pins):
    note = (source / "modules" / "architecture.md").read_text(encoding="utf-8")
    anchors = list(SECTION.finditer(note))
    if len(anchors) != 1:
        return {"status": "missing-heading"}
    following = NEXT_SECTION.search(note, anchors[0].end())
    section = note[anchors[0].end():following.start() if following else len(note)]
    fence = FENCE.fullmatch(section)
    if not fence:
        return {"status": "missing-or-invalid-fence"}
    try:
        rows = json.loads(fence[2])
    except ValueError:
        return {"status": "invalid-json"}
    if not isinstance(rows, list) or not 1 <= len(rows) <= 8:
        return {"status": "invalid-example-count"}
    if any(type(row) is not dict or set(row) != {"id", "recipe", "stdin", "expectedExitCode", "expectedJson"} or
           row["recipe"] != "engineering-json" or not isinstance(row["stdin"], str) or
           type(row["expectedExitCode"]) is not int or not isinstance(row["expectedJson"], dict) or
           not isinstance(row["id"], str) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,79}", row["id"])
           for row in rows) or len({row["id"] for row in rows}) != len(rows):
        return {"status": "invalid-example-contract"}
    details = []
    with TemporaryDirectory(prefix="example-audit-", dir=ROOT / "tmp-probe-preflight") as directory:
        scratch = Path(directory)
        for name in PATHS:
            content = (source / name).read_bytes()
            if sha256(content).hexdigest() != pins[name]:
                raise ValueError("Frozen artifact digest does not match the benchmark record")
            (scratch / name).write_bytes(content)
        for row in rows:
            actual, exit_code, failure = execute(scratch, row["stdin"])
            expected = row["expectedJson"]
            matched = (exit_code == row["expectedExitCode"] and type(actual) is dict and actual == expected and
                       ("units" not in expected or type(actual["units"]) is type(expected["units"])))
            details.append({"id": row["id"], "stdin": row["stdin"], "expected": expected, "actual": actual,
                            "expectedExitCode": row["expectedExitCode"], "exitCode": exit_code, "failure": failure,
                            "matched": matched})
    return {"status": "tested", "cases": details}


def main():
    reports = []
    for name in sys.argv[1:]:
        run = (ROOT / name).resolve(strict=True)
        if not run.is_relative_to(ROOT):
            raise SystemExit("Use the isolated G QA root")
        for mode in ("standard", "building-loop"):
            for stage in ("g1", "g2"):
                path = run / f"{mode}-{stage}.json"
                if not path.is_file():
                    continue
                summary = json.loads(path.read_text(encoding="utf-8"))
                for sample, measurement in (("final", summary), ("comparison", summary["comparison"])):
                    source = run / ("frozen" if sample == "final" else "checkpoint") / mode / stage
                    if not source.is_dir():
                        continue
                    pins = {row["path"]: row["sha256"] for row in measurement["after"]}
                    reports.append({"run": name, "mode": mode, "stage": stage, "sample": sample,
                                    "noteSha256": measurement["notes"]["sha256"], **audit(source, pins)})
    print(json.dumps({"scope": "Independent replay of declared examples. No effect on the fixed signed scores.",
                      "observations": reports}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

