            dependents[dep].append(change_id)
    ready = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for child in dependents[change_id]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(by_id):
        # A cycle anywhere in the graph fails the whole request, even when the
        # cycle sits entirely inside already applied changes.
        return None
    return order


def _retained_ids(by_id, applied, retain):
    """Close the retain list over applied transitive dependencies.

    A retained change may only stay if the changes it was built on stay too,
    so walk depends_on from each retained ID and keep every hit that is
    applied. Dependencies that are not applied are skipped because there is
    nothing applied to preserve them. The graph is known to be acyclic and
    every target known at this point, so the walk terminates.
    """
    kept = set()
    pending = [change_id for change_id in retain if change_id in applied]
    while pending:
        change_id = pending.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        pending.extend(dep for dep in by_id[change_id]["depends_on"] if dep in applied)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        # G2 validates retain shape on every request, so a plan carrying a
        # malformed retain list is refused as invalid-retain rather than having
        # the field silently ignored.
        retain = read_retain(request.get("retain"))
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    by_id = {change["id"]: change for change in changes}
    # Unknown targets are reported before cycle detection so the caller gets the
    # concrete missing ID rather than a generic rotation error.
    if not _check_targets(by_id):
        return failure("unknown-dependency")
    order = _topological_order(by_id)
    if order is None:
        return failure("dependency-cycle")
    if not applied <= by_id.keys():
        # A journal entry with no matching change means the persisted journal
        # and the release spec disagree; treating it as already satisfied
        # would hide that drift, so fail closed.
        return failure("unknown-dependency")
    if request["action"] == "rollback":
        if not set(retain) <= applied:
            # Retaining an ID that was never applied is drift between the
            # request and the journal; guessing would silently change which
            # of the caller's changes survive the rollback, so fail closed
            # before emitting any action.
            return failure("invalid-retain")
        kept = _retained_ids(by_id, applied, retain)
        # Reverse the *full* order before filtering to applied, so rollback
        # respects the same relative ordering the plan would have emitted;
        # ordering only the applied subgraph would allow contradictions.
        # Retained IDs are then removed from that same sequence, which keeps
        # the remaining rollback order identical to a rollback without retain.
        selected = [
            by_id[change_id] for change_id in reversed(order)
            if change_id in applied and change_id not in kept
        ]
    else:
        selected = [by_id[change_id] for change_id in order if change_id not in applied]
    units = total_units(selected)
    if request["action"] == "plan" and units > budget:
        # Measured on what is actually emitted: replay has already collapsed
        # duplicates and applied entries were already dropped.
        return failure("budget-exceeded")
    return {"status": "ok", "actions": [change["id"] for change in selected], "units": units}

policy.py.text:
"""Validate release policy before computing actions."""


class PolicyError(ValueError):
    pass


# G2 is staging-only. Both actions stay in the whitelist so a malformed action
# on a non-frozen environment still reports unsupported-action.
ACTIONS = {"plan", "rollback"}

# G2 freezes production for both plan and rollback. The check sits in front of
# the action and budget checks so a production request is refused as
# production-frozen even when its action or budget is also malformed, and it
# runs before any graph or journal work in planner.plan, so a malformed graph
# can never be reported ahead of the freeze or leak partial actions.
FROZEN_ENVIRONMENTS = {"production"}

# G2 staging plan budget is capped at 3 units regardless of what the request
# asks for; a larger request still fails with budget-exceeded. The cap is a
# planning limit only: rollback validates its budget but is not capped.
STAGING_PLAN_LIMIT = 3


def limit_for(request):
    environment = request.get("environment")
    if environment not in {"staging", "production"}:
        raise PolicyError("invalid-environment")
    if environment in FROZEN_ENVIRONMENTS:
        raise PolicyError("production-frozen")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    # type() is used instead of isinstance so bools, which subclass int,
    # are rejected as malformed budgets.
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return min(budget, STAGING_PLAN_LIMIT)

