"""Normalize release records at the input boundary.

This module owns input validation, replay identity and the persisted applied
journal. It never imports policy, planner or the entrypoint.
"""


class JournalError(ValueError):
    pass


def _identity(change):
    """Replay identity: id, component, units and the *set* of dependencies.

    Dependency order and repetition carry no meaning for graph construction, so
    two rows that differ only in ``depends_on`` ordering are the same change and
    must collapse before accounting (units are summed over the collapsed rows).
    """
    return (change["id"], change["component"], change["units"], frozenset(change["depends_on"]))


def _check_id_list(value, code):
    if not isinstance(value, list):
        raise JournalError(code)
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError(code)
    return list(value)


def _read_change(row):
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    change_id = row.get("id")
    component = row.get("component")
    if not isinstance(change_id, str) or not change_id:
        raise JournalError("invalid-change")
    if not isinstance(component, str) or not component:
        raise JournalError("invalid-change")
    # ``type(...) is not int`` also rejects booleans, which Python counts as
    # ints but are not valid units.
    if type(row.get("units")) is not int or row["units"] < 1:
        raise JournalError("invalid-change")
    return {
        "id": change_id,
        "component": component,
        "units": row["units"],
        "depends_on": _check_id_list(row.get("depends_on", []), "invalid-change"),
    }


def read_changes(records):
    """Validate rows, collapse identical duplicates, reject conflicting ones."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    by_id = {}
    for row in records:
        change = _read_change(row)
        seen = by_id.get(change["id"])
        if seen is None:
            by_id[change["id"]] = change
        elif _identity(seen) != _identity(change):
            # The same id describes different content: executing either one
            # would be arbitrary, so fail closed instead of picking a winner.
            raise JournalError("conflicting-change")
    return list(by_id.values())


def read_applied(request):
    """Return the caller-supplied persisted journal as a set of ids."""
    return set(_check_id_list(request.get("applied", []), "invalid-change"))


def read_retain(request):
    """Return the rollback retain set.

    ``retain`` is a rollback-only field (CHANGE-G2.md item 3) and is read after
    the journal so membership can be checked against applied ids. Every element
    is validated before any subtraction, so a malformed list can never produce
    a partially reduced action list.
    """
    retain = _check_id_list(request.get("retain", []), "invalid-retain")
    if len(set(retain)) != len(retain):
        raise JournalError("invalid-retain")
    return set(retain)

