"""Compose policy and journal data into a plan.

This module owns graph construction, ordering and result assembly. It imports
policy and journal; neither of them may import this module.
"""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, authorize, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _order(changes, applied):
    """Validate the dependency graph and return the deterministic topological order.

    Edges point from a change to what it depends on; a change is eligible only
    when every dependency is already ordered or present in the persisted
    applied journal -- an applied dependency is satisfied and consumes nothing.
    Missing targets (including unknown ids in ``applied``) and cycles fail with
    ``unknown-dependency`` / ``dependency-cycle`` before any output is built, so
    a broken graph can never yield a partial action list.
    """
    by_id = {change["id"]: change for change in changes}
    for target in applied:
        if target not in by_id:
            raise JournalError("unknown-dependency")
    remaining = {}
    dependents = {}
    for change in changes:
        deps = set(change["depends_on"])
        unknown = deps - by_id.keys()
        if unknown:
            raise JournalError("unknown-dependency")
        remaining[change["id"]] = len(deps)
        for dep in deps:
            dependents.setdefault(dep, []).append(change["id"])
    ready = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        # The heap gives lexicographic tie-breaking among currently eligible ids.
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents.get(change_id, ()):
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order, by_id


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy first: environment/action/budget gates (including the
        # production freeze) must answer before changes are even parsed.
        action = authorize(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        retain = read_retain(request) if action == "rollback" else set()
        if action == "rollback" and not retain <= applied:
            # Retaining something that is not applied would silently emit an
            # action for a change the journal never recorded.
            raise JournalError("invalid-retain")
        order, by_id = _order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if action == "plan":
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(by_id[change_id]["units"] for change_id in actions)
        # Checked after replay/dedup, against emitted units only; the effective
        # limit already folds in the staging cap.
        if units > limit_for(request, action):
            return failure("budget-exceeded")
        return {"status": "ok", "actions": actions, "units": units}
    kept = _retained_closure(retain, by_id, applied)
    actions = [change_id for change_id in reversed(order)
               if change_id in applied and change_id not in kept]
    return {"status": "ok", "actions": actions, "units": sum(by_id[c]["units"] for c in actions)}


def _retained_closure(retain, by_id, applied):
    """Retained ids plus the applied transitive dependencies they still require.

    Retention keeps a change in place, so whatever applied change it depends on
    must stay as well; without the closure a retained change would be left
    running on top of rolled-back dependencies.
    """
    kept = set()
    stack = list(retain)
    while stack:
        change_id = stack.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        for dep in by_id[change_id]["depends_on"]:
            if dep in applied:
                stack.append(dep)
    return kept

